package io.forgeloop.control.api;
import io.forgeloop.control.application.*; import io.forgeloop.control.domain.*; import java.util.*; import org.springframework.graphql.data.method.annotation.*; import org.springframework.stereotype.Controller;
@Controller public class ControlPlaneController { private final FeatureRunService runs; public ControlPlaneController(FeatureRunService runs){this.runs=runs;} @QueryMapping public FeatureRun featureRun(@Argument String id){return runs.get(id);}@QueryMapping public List<FeatureRun> featureRuns(){return runs.list();}@MutationMapping public FeatureRun submitFeature(@Argument SubmitFeatureInput input){return runs.submit(new FeatureSubmission(input.repository(),input.sourceRef(),input.title(),input.specification(),input.budgetUsd()));}@MutationMapping public DeliveryTask transitionTask(@Argument String taskId,@Argument TaskState to){return runs.transitionTask(taskId,to);} public record SubmitFeatureInput(String repository,String sourceRef,String title,String specification,double budgetUsd){} }
